-- ═══════════════════════════════════════════════════════════════════════════
--  0162 — Khalidiyah's 21 indicator views from the reviewed workbook's
--         'Calculation formulas' sheet
--
--  GENERATED by supabase/khalidiyah/gen_views.py (the views by hand, one per
--  indicator under the sheet's own formula; the framework text read from the
--  workbook). One view per indicator, the shape of the other forty:
--  (period_code, actual, denominator, municipality_id), anchored on
--  `municipality m where m.code = 'KHLD'`, joined to data on
--  municipality_id as well as on date (0114), live rows only.
--
--  ── THE WINDOW EACH READS ──
--
--  The sheet's shared definition: "Every indicator is filtered on its date
--  field within the reporting quarter / year; cumulative indicators use date
--  <= report date." Each indicator's Frequency column says which it is, and
--  the view for a quarter reads, up to that quarter's end:
--
--    the year to date   the annual ones -- IMP-0, SO1-0, SO2-0, SO4-0
--                       (surveys "in reporting year"), A3 ("F183 in
--                       reporting year"), C2 ("F024 in reporting year")
--    everything to date the cumulative ones -- A2 ("F016 <= report date"),
--                       D1 ("cumulative from Dec 2026"), D2, F2, F3, G1, G2,
--                       H1, H2 ("cumulative"), C1 ("latest report"), SO3-0
--                       ("annual / end of period", over all registered)
--    the milestones     A1, B1, E1, F1: 1 from the quarter of the first
--                       record that establishes them, 0 before it
--
--  A quarter that has not begun reads nothing (NULL), never a repeat of the
--  total to date. The dashboard shows the current quarter, so every figure
--  on it is the sheet's to-date or year-to-date number. The date field of
--  each record is the sheet's own (F016, F183, F024, F031, F037, F068, F092,
--  F110, F159, F173, F198, F205); F159 is a timestamp, read in Amman's time.
--
--  ── WHAT EACH COUNTS ──
--
--    ratios      IMP-0 (F166 in 4-5 over F166 answered; consent, resident),
--                SO2-0 (F170 in 4-5 over F170 answered; consent), SO1-0 and
--                SO4-0 (the latest response per partner / producer in the
--                quarter; Yes over surveyed) -- x100, one decimal, NULL when
--                the denominator is 0
--    records     A2 (coordination meetings with partners whose attendance
--                sheet F120 is filed), C2 (campaigns held), D1 (activities
--                held, from 1 December 2026), H2 (vendor attendances at
--                markets held -- participations)
--    sums        A3 (JOD, F186), D2 (F039 at held activities), F3 (F127
--                of campaigns held), H1 (F094 of markets held -- days)
--    people      F2 (volunteers with an attendance, on the first), G1
--                (owners who attended all four core topics, on the day the
--                fourth was reached), G2 (owners with a support, on the first)
--    latest      C1 (F122 of the latest report on or before the quarter's
--                end, over its F121)
--    milestones  A1, B1, F1 (FORM-22: the status and all four components),
--                E1 (a founding meeting with its minutes filed, FORM-11, or
--                FORM-22's record)
--
--  A public volunteer registration counts once staff approve it
--  (application_status, 0159). Every choice the sheet leaves open is in
--  06_OPEN_QUESTIONS.md, not decided silently here: SO3-0's denominator
--  (the sheet's own, all registered volunteers), G1's simplification (the
--  four core topics; cycles are not defined), D1's bazaar exclusion (not
--  applied: no field says an activity is also a FORM-16 market).
--
--  ── THE SECOND FIGURES, AND WHAT CANNOT COMPUTE ──
--
--  v_khld_indicator_unique carries the figures the sheet asks for beside the
--  main one: A3's number of contributions, H1's number of markets ("report
--  both markets and days"), H2's unique vendors ("unique F112"). Every
--  indicator computes, so v_khld_indicator_status names no reason; it keeps
--  its columns because every dashboard reads it.
--
--  ── v_indicator_actual ──
--
--  Recreated from its CURRENT definition (0153's) with the 21 Khalidiyah
--  branches back, in 0163; that migration asserts every Sahel Horan and
--  Ramtha row is unchanged, and revokes the leaf views and the helpers from
--  every client role. Split in two only for the size of one applied text.
-- ═══════════════════════════════════════════════════════════════════════════

-- ── the framework, brought to the reviewed workbook ───────────────────────
update public.indicator i set formula = '[ COUNT(FORM-19 WHERE F166 IN (4,5)) ÷ COUNT(FORM-19 WHERE F166 IS NOT NULL) ] × 100', data_source = 'khld_park_survey', view_name = 'v_ind_khld_imp_0'
  from public.municipality m where m.id = i.municipality_id and m.code = 'KHLD' and i.code = 'IMP-0';
update public.indicator i set formula = '[ COUNT DISTINCT(F174 WHERE F179 = "Yes") ÷ COUNT DISTINCT(F174) ] × 100', data_source = 'khld_partner_survey', view_name = 'v_ind_khld_so1_0'
  from public.municipality m where m.id = i.municipality_id and m.code = 'KHLD' and i.code = 'SO1-0';
update public.indicator i set formula = 'Established = 1 IF F194 IN ("Established","Updated") AND F190 contains all 4 components; else 0', data_source = 'khld_milestone_record', view_name = 'v_ind_khld_a1'
  from public.municipality m where m.id = i.municipality_id and m.code = 'KHLD' and i.code = 'A1';
update public.indicator i set formula = 'COUNT(FORM-05 WHERE F117 = "Coordination meeting with partners" AND F016 ≤ report date)', data_source = 'khld_meeting', view_name = 'v_ind_khld_a2'
  from public.municipality m where m.id = i.municipality_id and m.code = 'KHLD' and i.code = 'A2';
update public.indicator i set formula = 'Total value = SUM(FORM-21.F186); Number of contributions = COUNT(FORM-21)', data_source = 'khld_contribution', view_name = 'v_ind_khld_a3'
  from public.municipality m where m.id = i.municipality_id and m.code = 'KHLD' and i.code = 'A3';
update public.indicator i set formula = 'Established = 1 IF F194 IN ("Established","Updated") AND F191 contains all 4 components; else 0', data_source = 'khld_milestone_record', view_name = 'v_ind_khld_b1'
  from public.municipality m where m.id = i.municipality_id and m.code = 'KHLD' and i.code = 'B1';
update public.indicator i set formula = '[ COUNT(FORM-19 WHERE F170 IN (4,5)) ÷ COUNT(FORM-19 WHERE F170 IS NOT NULL) ] × 100', data_source = 'khld_park_survey', view_name = 'v_ind_khld_so2_0'
  from public.municipality m where m.id = i.municipality_id and m.code = 'KHLD' and i.code = 'SO2-0';
update public.indicator i set formula = 'Count = F122 (latest report); % = F122 ÷ F121 × 100', data_source = 'khld_rehab_report', view_name = 'v_ind_khld_c1'
  from public.municipality m where m.id = i.municipality_id and m.code = 'KHLD' and i.code = 'C1';
update public.indicator i set formula = 'COUNT(FORM-07 WHERE F126 = "Held" AND F024 in reporting year)', data_source = 'khld_campaign', view_name = 'v_ind_khld_c2'
  from public.municipality m where m.id = i.municipality_id and m.code = 'KHLD' and i.code = 'C2';
update public.indicator i set formula = 'COUNT(FORM-08 WHERE F130 = "Held" AND F031 ≤ report date)', data_source = 'khld_activity', view_name = 'v_ind_khld_d1'
  from public.municipality m where m.id = i.municipality_id and m.code = 'KHLD' and i.code = 'D1';
update public.indicator i set formula = 'Total = SUM(FORM-09.F039)', data_source = 'khld_activity_attendance', view_name = 'v_ind_khld_d2'
  from public.municipality m where m.id = i.municipality_id and m.code = 'KHLD' and i.code = 'D2';
update public.indicator i set formula = '[ COUNT(F070 WHERE COUNT DISTINCT(F147) ≥ 2) ÷ COUNT DISTINCT(FORM-12.F058) ] × 100', data_source = 'khld_volunteer_attendance', view_name = 'v_ind_khld_so3_0'
  from public.municipality m where m.id = i.municipality_id and m.code = 'KHLD' and i.code = 'SO3-0';
update public.indicator i set formula = 'Established = 1 IF COUNT(FORM-11 WHERE F142 = "Yes" AND F052 uploaded) ≥ 1 (or FORM-22 F189 = SO3-E1 AND F194 = "Established"); else 0', data_source = 'khld_committee_meeting', view_name = 'v_ind_khld_e1'
  from public.municipality m where m.id = i.municipality_id and m.code = 'KHLD' and i.code = 'E1';
update public.indicator i set formula = 'Established = 1 IF F194 = "Established" AND F193 contains all 4 components; else 0', data_source = 'khld_milestone_record', view_name = 'v_ind_khld_f1'
  from public.municipality m where m.id = i.municipality_id and m.code = 'KHLD' and i.code = 'F1';
update public.indicator i set formula = 'COUNT DISTINCT(FORM-12.F058 WHERE EXISTS FORM-13.F070 = F058)', data_source = 'khld_volunteer', view_name = 'v_ind_khld_f2'
  from public.municipality m where m.id = i.municipality_id and m.code = 'KHLD' and i.code = 'F2';
update public.indicator i set formula = 'SUM(FORM-07.F127 WHERE F126 = "Held")', data_source = 'khld_campaign', view_name = 'v_ind_khld_f3'
  from public.municipality m where m.id = i.municipality_id and m.code = 'KHLD' and i.code = 'F3';
update public.indicator i set formula = '[ COUNT DISTINCT(F206 WHERE F208 = "Yes") ÷ COUNT DISTINCT(F206) ] × 100', data_source = 'khld_producer_survey', view_name = 'v_ind_khld_so4_0'
  from public.municipality m where m.id = i.municipality_id and m.code = 'KHLD' and i.code = 'SO4-0';
update public.indicator i set formula = 'COUNT DISTINCT(F197 WHERE COUNT DISTINCT(F200 core & attended) = COUNT(FORM-14 WHERE F150 = "Yes" in that cycle))', data_source = 'khld_enterprise_support', view_name = 'v_ind_khld_g1'
  from public.municipality m where m.id = i.municipality_id and m.code = 'KHLD' and i.code = 'G1';
update public.indicator i set formula = 'COUNT DISTINCT(FORM-23.F197 WHERE F199 ≠ "Guidance session" OR F201 = "Attended")', data_source = 'khld_enterprise_support', view_name = 'v_ind_khld_g2'
  from public.municipality m where m.id = i.municipality_id and m.code = 'KHLD' and i.code = 'G2';
update public.indicator i set formula = 'Market days = SUM(FORM-16.F094 WHERE F154 = "Held"); Number of markets = COUNT(FORM-16 WHERE F154 = "Held")', data_source = 'khld_market', view_name = 'v_ind_khld_h1'
  from public.municipality m where m.id = i.municipality_id and m.code = 'KHLD' and i.code = 'H1';
update public.indicator i set formula = 'Participations = COUNT(FORM-18); Per market = COUNT(FORM-18 GROUP BY F157); Unique vendors = COUNT DISTINCT(FORM-18.F112)', data_source = 'khld_market_attendance', view_name = 'v_ind_khld_h2'
  from public.municipality m where m.id = i.municipality_id and m.code = 'KHLD' and i.code = 'H2';
-- SO2-C2's statement is the reviewed framework sheet's
update public.indicator i set name_en = 'Number of volunteer campaigns rehabilitation activities conducted'
  from public.municipality m where m.id = i.municipality_id and m.code = 'KHLD' and i.code = 'C2';

-- ── helpers ───────────────────────────────────────────────────────────────

-- The milestones: the first date each is established, per the sheet.
-- A1 / B1: F194 Established or Updated and all four F190 / F191 ticked.
-- F1: F194 Established and all four F193 ticked. E1: a FORM-11 founding
-- meeting (F142 Yes) with its minutes (F052) filed, or a FORM-22 record
-- with F194 Established.
create view public.v_khld_milestone_established as
select x.municipality_id, x.milestone, min(x.on_date) as established_on
  from (
    select r.municipality_id, ms.code as milestone, r.status_date as on_date
      from public.khld_milestone_record r
      join public.ref_khld_milestone ms on ms.id = r.milestone_id
      join public.ref_khld_milestone_status st on st.id = r.status_id
     where r.deleted_at is null and r.status_date is not null
       and ((ms.code in ('so1_a1', 'so1_b1') and st.code in ('established', 'updated'))
            or (ms.code in ('so3_e1', 'so3_f1') and st.code = 'established'))
       and (ms.code = 'so3_e1'
            or (select count(distinct o.option_id) from public.khld_milestone_record_option o
                 where o.milestone_record_id = r.id
                   and o.question_code = case ms.code when 'so1_a1' then 'f190' when 'so1_b1' then 'f191' else 'f193' end)
               = case ms.code
                   when 'so1_a1' then (select count(*) from public.ref_khld_components_a1 where deleted_at is null and is_active)
                   when 'so1_b1' then (select count(*) from public.ref_khld_components_b1 where deleted_at is null and is_active)
                   else (select count(*) from public.ref_khld_components_f1 where deleted_at is null and is_active) end)
    union all
    select c.municipality_id, 'so3_e1', c.meeting_date
      from public.khld_committee_meeting c
     where c.deleted_at is null and c.is_founding
       and exists (select 1 from public.attachment a
                    where a.entity_type = 'khld_committee_meeting' and a.entity_id = c.id
                      and a.field_code = 'F052' and a.deleted_at is null)
  ) x
 group by x.municipality_id, x.milestone;

-- A volunteer's attendances at live campaigns and activities; approved,
-- live volunteers only (SO3-0, SO3-F2).
create view public.v_khld_volunteer_occasion as
select a.municipality_id, a.volunteer_id, coalesce(a.campaign_id, a.activity_id) as occasion_id, a.report_date
  from public.khld_volunteer_attendance a
  join public.khld_volunteer v on v.id = a.volunteer_id and v.deleted_at is null and v.application_status = 'approved'
  join public.person p on p.id = v.person_id and p.deleted_at is null
 where a.deleted_at is null
   and (exists (select 1 from public.khld_campaign k where k.id = a.campaign_id and k.deleted_at is null)
        or exists (select 1 from public.khld_activity k where k.id = a.activity_id and k.deleted_at is null));

-- SO4-G1: an owner completes on the day the fourth core topic is attended
-- (the sheet's simplification: "completed = attended all 4 core topics").
create view public.v_khld_guidance_completed as
select t.municipality_id, t.person_id, max(t.first_on) as completed_on
  from (
    select s.municipality_id, s.person_id, tp.code as topic, min(s.support_date) as first_on
      from public.khld_enterprise_support s
      join public.ref_khld_support_type st on st.id = s.support_type_id and st.code = 'guidance'
      join public.khld_guidance_session g on g.id = s.session_id and g.deleted_at is null and g.is_core
      join public.ref_khld_session_topic tp on tp.id = g.topic_id and tp.code in ('basics', 'licensing', 'hygiene', 'marketing')
      join public.person p on p.id = s.person_id and p.deleted_at is null
     where s.deleted_at is null and s.attended
     group by s.municipality_id, s.person_id, tp.code
  ) t
 group by t.municipality_id, t.person_id
having count(distinct t.topic) = 4;

-- ── IMP-0 ·
--    formula: "[ COUNT(FORM-19 WHERE F166 IN (4,5)) ÷ COUNT(FORM-19 WHERE
--      F166 IS NOT NULL) ] × 100"
--    frequency: "Annual"
create view public.v_ind_khld_imp_0 as
select rp.code as period_code,
       case when count(s.id) = 0 then null::numeric
            else round(100.0 * count(*) filter (where s.interaction_score >= 4) / count(s.id), 1) end as actual,
       count(s.id)::numeric as denominator,
       m.id as municipality_id
  from public.municipality m
  join public.reporting_period rp on rp.municipality_id = m.id
  left join public.khld_park_survey s
    on s.municipality_id = m.id and s.deleted_at is null and s.consent and s.is_resident
   and s.interaction_score is not null
   and (s.surveyed_at at time zone 'Asia/Amman')::date between date_trunc('year', rp.end_date)::date and rp.end_date
   and rp.start_date <= current_date
 where m.code = 'KHLD'
 group by m.id, rp.code;

-- ── SO1-0 ·
--    formula: "[ COUNT DISTINCT(F174 WHERE F179 = "Yes") ÷ COUNT
--      DISTINCT(F174) ] × 100"
--    frequency: "Annual"
create view public.v_ind_khld_so1_0 as
select rp.code as period_code,
       case when count(l.partner_id) = 0 then null::numeric
            else round(100.0 * count(*) filter (where l.overall_effective) / count(l.partner_id), 1) end as actual,
       count(l.partner_id)::numeric as denominator,
       m.id as municipality_id
  from public.municipality m
  join public.reporting_period rp on rp.municipality_id = m.id
  left join lateral (
    select distinct on (s.partner_id) s.partner_id, s.overall_effective
      from public.khld_partner_survey s
      join public.khld_partner p on p.id = s.partner_id and p.deleted_at is null
     where s.municipality_id = m.id and s.deleted_at is null
       and s.survey_date between date_trunc('year', rp.end_date)::date and rp.end_date
       and rp.start_date <= current_date
     order by s.partner_id, s.survey_date desc, s.created_at desc
  ) l on true
 where m.code = 'KHLD'
 group by m.id, rp.code;

-- ── A1 ·
--    formula: "Established = 1 IF F194 IN ("Established","Updated") AND F190
--      contains all 4 components; else 0"
--    frequency: "Once (within 6 months of Plan adoption)"
create view public.v_ind_khld_a1 as
select rp.code as period_code,
       case when rp.start_date > current_date then null when e.established_on <= rp.end_date then 1 else 0 end::numeric as actual,
       null::numeric as denominator, m.id as municipality_id
  from public.municipality m
  join public.reporting_period rp on rp.municipality_id = m.id
  left join public.v_khld_milestone_established e on e.municipality_id = m.id and e.milestone = 'so1_a1'
 where m.code = 'KHLD';

-- ── A2 ·
--    formula: "COUNT(FORM-05 WHERE F117 = "Coordination meeting with
--      partners" AND F016 ≤ report date)"
--    frequency: "Quarterly / cumulative"
create view public.v_ind_khld_a2 as
select rp.code as period_code, case when rp.start_date > current_date then null else count(x.id) end::numeric as actual, null::numeric as denominator, m.id as municipality_id
  from public.municipality m
  join public.reporting_period rp on rp.municipality_id = m.id
  left join (public.khld_meeting x
             join public.ref_khld_meeting_type t on t.id = x.meeting_type_id and t.code = 'partner_coordination')
    on x.municipality_id = m.id and x.deleted_at is null and x.meeting_date <= rp.end_date
   and exists (select 1 from public.attachment a
                where a.entity_type = 'khld_meeting' and a.entity_id = x.id and a.field_code = 'F120' and a.deleted_at is null)
 where m.code = 'KHLD'
 group by m.id, rp.code, rp.start_date;

-- ── A3 ·
--    formula: "Total value = SUM(FORM-21.F186); Number of contributions =
--      COUNT(FORM-21)"
--    frequency: "Annual"
create view public.v_ind_khld_a3 as
select rp.code as period_code, case when rp.start_date > current_date then null else coalesce(sum(x.value_jod), 0) end::numeric as actual, null::numeric as denominator, m.id as municipality_id
  from public.municipality m
  join public.reporting_period rp on rp.municipality_id = m.id
  left join public.khld_contribution x
    on x.municipality_id = m.id and x.deleted_at is null
   and x.date_received between date_trunc('year', rp.end_date)::date and rp.end_date
 where m.code = 'KHLD'
 group by m.id, rp.code, rp.start_date;

-- ── B1 ·
--    formula: "Established = 1 IF F194 IN ("Established","Updated") AND F191
--      contains all 4 components; else 0"
--    frequency: "Once (within first year), then updates"
create view public.v_ind_khld_b1 as
select rp.code as period_code,
       case when rp.start_date > current_date then null when e.established_on <= rp.end_date then 1 else 0 end::numeric as actual,
       null::numeric as denominator, m.id as municipality_id
  from public.municipality m
  join public.reporting_period rp on rp.municipality_id = m.id
  left join public.v_khld_milestone_established e on e.municipality_id = m.id and e.milestone = 'so1_b1'
 where m.code = 'KHLD';

-- ── SO2-0 ·
--    formula: "[ COUNT(FORM-19 WHERE F170 IN (4,5)) ÷ COUNT(FORM-19 WHERE
--      F170 IS NOT NULL) ] × 100"
--    frequency: "Annual"
create view public.v_ind_khld_so2_0 as
select rp.code as period_code,
       case when count(s.id) = 0 then null::numeric
            else round(100.0 * count(*) filter (where s.satisfaction_score >= 4) / count(s.id), 1) end as actual,
       count(s.id)::numeric as denominator,
       m.id as municipality_id
  from public.municipality m
  join public.reporting_period rp on rp.municipality_id = m.id
  left join public.khld_park_survey s
    on s.municipality_id = m.id and s.deleted_at is null and s.consent
   and s.satisfaction_score is not null
   and (s.surveyed_at at time zone 'Asia/Amman')::date between date_trunc('year', rp.end_date)::date and rp.end_date
   and rp.start_date <= current_date
 where m.code = 'KHLD'
 group by m.id, rp.code;

-- ── C1 ·
--    formula: "Count = F122 (latest report); % = F122 ÷ F121 × 100"
--    frequency: "Per report during rehabilitation"
create view public.v_ind_khld_c1 as
select rp.code as period_code,
       case when rp.start_date > current_date then null else l.completed_count end::numeric as actual,
       case when rp.start_date > current_date then null else l.agreed_total end::numeric as denominator,
       m.id as municipality_id
  from public.municipality m
  join public.reporting_period rp on rp.municipality_id = m.id
  left join lateral (
    select r.completed_count, r.agreed_total
      from public.khld_rehab_report r
     where r.municipality_id = m.id and r.deleted_at is null and r.report_date <= rp.end_date
     order by r.report_date desc, r.created_at desc
     limit 1
  ) l on true
 where m.code = 'KHLD';

-- ── C2 ·
--    formula: "COUNT(FORM-07 WHERE F126 = "Held" AND F024 in reporting year)"
--    frequency: "Annual (≥ 4)"
create view public.v_ind_khld_c2 as
select rp.code as period_code, case when rp.start_date > current_date then null else count(x.id) end::numeric as actual, null::numeric as denominator, m.id as municipality_id
  from public.municipality m
  join public.reporting_period rp on rp.municipality_id = m.id
  left join (public.khld_campaign x join public.ref_khld_event_status s on s.id = x.status_id and s.code = 'held')
    on x.municipality_id = m.id and x.deleted_at is null
   and x.start_date between date_trunc('year', rp.end_date)::date and rp.end_date
 where m.code = 'KHLD'
 group by m.id, rp.code, rp.start_date;

-- ── D1 ·
--    formula: "COUNT(FORM-08 WHERE F130 = "Held" AND F031 ≤ report date)"
--    frequency: "Cumulative from Dec 2026"
create view public.v_ind_khld_d1 as
select rp.code as period_code, case when rp.start_date > current_date then null else count(x.id) end::numeric as actual, null::numeric as denominator, m.id as municipality_id
  from public.municipality m
  join public.reporting_period rp on rp.municipality_id = m.id
  left join (public.khld_activity x join public.ref_khld_event_status s on s.id = x.status_id and s.code = 'held')
    on x.municipality_id = m.id and x.deleted_at is null and x.start_date >= date '2026-12-01'
   and x.start_date <= rp.end_date
 where m.code = 'KHLD'
 group by m.id, rp.code, rp.start_date;

-- ── D2 ·
--    formula: "Total = SUM(FORM-09.F039)"
--    frequency: "Every event; cumulative"
create view public.v_ind_khld_d2 as
select rp.code as period_code, case when rp.start_date > current_date then null else coalesce(sum(x.total_participants), 0) end::numeric as actual, null::numeric as denominator, m.id as municipality_id
  from public.municipality m
  join public.reporting_period rp on rp.municipality_id = m.id
  left join (public.khld_activity_attendance x
             join public.khld_activity a on a.id = x.activity_id and a.deleted_at is null
             join public.ref_khld_event_status s on s.id = a.status_id and s.code = 'held')
    on x.municipality_id = m.id and x.deleted_at is null and x.report_date <= rp.end_date
 where m.code = 'KHLD'
 group by m.id, rp.code, rp.start_date;
